//
// 2026-05-20 — converted from ES6 to named AMD by hand. See sibling
// program_actions.min.js + classroom_actions.min.js for the rationale.
// amd/src/ remains canonical ES6; behaviour changes must happen in BOTH
// places until Grunt is wired in.

define('local_airpay_learningpath/path_actions', [
    'core_form/modalform',
    'core/str',
    'core/notification',
    'core/ajax'
], function(ModalForm, Str, Notification, Ajax) {
    'use strict';

    var getString = Str.get_string;

    // ════════════════════════════════════════════════════════════════════
    // Path-level actions (index page)
    // ════════════════════════════════════════════════════════════════════

    var openPathForm = function(pathid, returnFocus) {
        var titleKey = (pathid === 0) ? 'addpath' : 'editpath';
        return getString(titleKey, 'local_airpay_learningpath').then(function(title) {
            var modalForm = new ModalForm({
                formClass: 'local_airpay_learningpath\\form\\edit_path',
                args: {pathid: pathid},
                modalConfig: {title: title, large: true},
                returnFocus: returnFocus
            });
            modalForm.addEventListener(modalForm.events.FORM_SUBMITTED, function(event) {
                var message = (event.detail && event.detail.message) || 'Saved.';
                Notification.addNotification({message: message, type: 'success'});
                window.location.reload();
            });
            modalForm.show();
        });
    };

    var confirmStatus = function(pathid, name, makeActive, returnFocus) {
        var titleKey = makeActive ? 'activatepath' : 'archivepath';
        var msgKey = makeActive ? 'confirmactivate' : 'confirmarchive';
        return Promise.all([
            getString(titleKey, 'local_airpay_learningpath'),
            getString(msgKey, 'local_airpay_learningpath', name),
            getString('pathstatuschanged', 'local_airpay_learningpath')
        ]).then(function(strings) {
            var title = strings[0], message = strings[1], success = strings[2];
            Notification.confirm(title, message, title, null, function() {
                Ajax.call([{methodname: 'local_airpay_learningpath_toggle_status',
                            args: {pathid: pathid, active: makeActive}}])[0]
                    .then(function() {
                        Notification.addNotification({message: success, type: 'success'});
                        window.location.reload();
                        return null;
                    }).catch(Notification.exception);
            });
            if (returnFocus) {
                setTimeout(function() { returnFocus.focus(); }, 100);
            }
        });
    };

    var confirmDelete = function(pathid, name, returnFocus) {
        return Promise.all([
            getString('deletepath', 'local_airpay_learningpath'),
            getString('confirmdelete', 'local_airpay_learningpath', name),
            getString('delete', 'core'),
            getString('pathdeleted', 'local_airpay_learningpath')
        ]).then(function(strings) {
            var title = strings[0], message = strings[1], label = strings[2], success = strings[3];
            Notification.deleteCancelPromise(title, message, label, returnFocus).then(function() {
                Ajax.call([{methodname: 'local_airpay_learningpath_delete_path',
                            args: {pathid: pathid}}])[0]
                    .then(function() {
                        Notification.addNotification({message: success, type: 'success'});
                        window.location.reload();
                        return null;
                    }).catch(Notification.exception);
                return true;
            }, function() { return null; });
        });
    };

    // ════════════════════════════════════════════════════════════════════
    // Detail-page actions (G-04) — assign courses + enrol users
    // ════════════════════════════════════════════════════════════════════

    var refreshTable = function(rootEl) {
        window.location.reload();
    };

    var openAssignCoursesForm = function(pathid, returnFocus) {
        return getString('add_courses', 'local_airpay_learningpath').then(function(title) {
            var modalForm = new ModalForm({
                formClass: 'local_airpay_learningpath\\form\\assign_courses_form',
                args: {pathid: pathid},
                modalConfig: {title: title, large: true},
                returnFocus: returnFocus
            });
            modalForm.addEventListener(modalForm.events.FORM_SUBMITTED, function(event) {
                var detail = event.detail || {};
                var inserted = detail.inserted || 0;
                var message = inserted + ' course' + (inserted === 1 ? '' : 's') + ' added.';
                Notification.addNotification({message: message, type: 'success'});
                refreshTable();
            });
            modalForm.show();
        });
    };

    var openEnrolUsersForm = function(pathid, returnFocus) {
        return getString('enrol_users', 'local_airpay_learningpath').then(function(title) {
            var modalForm = new ModalForm({
                formClass: 'local_airpay_learningpath\\form\\enrol_users_form',
                args: {pathid: pathid},
                modalConfig: {title: title, large: true},
                returnFocus: returnFocus
            });
            modalForm.addEventListener(modalForm.events.FORM_SUBMITTED, function(event) {
                var detail = event.detail || {};
                var enrolled = detail.enrolled || 0;
                var message = enrolled + ' user' + (enrolled === 1 ? '' : 's') + ' enrolled.';
                Notification.addNotification({message: message, type: 'success'});
                refreshTable();
            });
            modalForm.show();
        });
    };

    // P1 #11 (2026-05-16) — bulk enrol by target audience.
    var openBulkEnrolAudienceForm = function(pathid, returnFocus) {
        return getString('audience_modal_title', 'local_airpay_learningpath').then(function(title) {
            var modalForm = new ModalForm({
                formClass: 'local_airpay_learningpath\\form\\bulk_enrol_audience_form',
                args: {pathid: pathid},
                modalConfig: {title: title, large: true},
                returnFocus: returnFocus
            });
            modalForm.addEventListener(modalForm.events.LOADED, function() {
                var modalBody = document.querySelector('.modal.show .modal-body')
                    || document.querySelector('.modal-body');
                if (modalBody) {
                    require(['local_airpay_learningpath/audience_form_helper'], function(helper) {
                        helper.init(modalBody);
                    });
                }
            });
            modalForm.addEventListener(modalForm.events.FORM_SUBMITTED, function(event) {
                var detail = event.detail || {};
                var enrolled = detail.enrolled || 0;
                var matched = detail.matched || 0;
                var message = enrolled === matched
                    ? 'Enrolled all ' + enrolled + ' matching user' + (enrolled === 1 ? '' : 's') + '.'
                    : enrolled + ' of ' + matched + ' matching users enrolled (rest were already enrolled).';
                Notification.addNotification({message: message, type: 'success'});
                refreshTable();
            });
            modalForm.show();
        });
    };

    var confirmUnassignCourse = function(pathid, courseid, name, returnFocus) {
        return Promise.all([
            getString('add_courses', 'local_airpay_learningpath'),
            getString('confirm_unassign_course', 'local_airpay_learningpath', name),
            getString('delete', 'core')
        ]).then(function(strings) {
            var title = strings[0], message = strings[1], label = strings[2];
            Notification.deleteCancelPromise(title, message, label, returnFocus).then(function() {
                Ajax.call([{methodname: 'local_airpay_learningpath_unassign_course',
                            args: {pathid: pathid, courseid: courseid}}])[0]
                    .then(function() {
                        Notification.addNotification({
                            message: 'Course removed from path.',
                            type: 'success'
                        });
                        refreshTable();
                        return null;
                    }).catch(Notification.exception);
                return true;
            }, function() { return null; });
        });
    };

    var confirmUnenrolUser = function(pathid, userid, name, returnFocus) {
        return Promise.all([
            getString('enrol_users', 'local_airpay_learningpath'),
            getString('confirm_unenrol_user', 'local_airpay_learningpath', name),
            getString('delete', 'core')
        ]).then(function(strings) {
            var title = strings[0], message = strings[1], label = strings[2];
            Notification.deleteCancelPromise(title, message, label, returnFocus).then(function() {
                Ajax.call([{methodname: 'local_airpay_learningpath_unenrol_user',
                            args: {pathid: pathid, userid: userid}}])[0]
                    .then(function() {
                        Notification.addNotification({
                            message: 'User unenrolled.',
                            type: 'success'
                        });
                        refreshTable();
                        return null;
                    }).catch(Notification.exception);
                return true;
            }, function() { return null; });
        });
    };

    // ════════════════════════════════════════════════════════════════════
    // Click delegators
    // ════════════════════════════════════════════════════════════════════

    var handleIndexClick = function(event) {
        var trigger = event.target.closest('[data-action]');
        if (!trigger) { return; }
        var action = trigger.dataset.action;
        var pathid = parseInt(trigger.dataset.pathid || '0', 10);
        var name = trigger.dataset.name || 'this path';
        switch (action) {
            case 'create-path':   event.preventDefault(); openPathForm(0, trigger); break;
            case 'edit-path':     event.preventDefault(); openPathForm(pathid, trigger); break;
            case 'archive-path':  event.preventDefault(); confirmStatus(pathid, name, false, trigger); break;
            case 'activate-path': event.preventDefault(); confirmStatus(pathid, name, true, trigger); break;
            case 'delete-path':   event.preventDefault(); confirmDelete(pathid, name, trigger); break;
        }
    };

    var handleViewClick = function(pathid) {
        return function(event) {
            var trigger = event.target.closest('[data-action]');
            if (!trigger) { return; }
            var action = trigger.dataset.action;
            var courseid = parseInt(trigger.dataset.courseid || '0', 10);
            var userid = parseInt(trigger.dataset.userid || '0', 10);
            var name = trigger.dataset.name || 'this item';
            switch (action) {
                case 'add-courses':
                    event.preventDefault();
                    openAssignCoursesForm(pathid, trigger);
                    break;
                case 'enrol-users':
                    event.preventDefault();
                    openEnrolUsersForm(pathid, trigger);
                    break;
                case 'bulk-enrol-audience':
                    event.preventDefault();
                    openBulkEnrolAudienceForm(pathid, trigger);
                    break;
                case 'unassign-course':
                    event.preventDefault();
                    confirmUnassignCourse(pathid, courseid, name, trigger);
                    break;
                case 'unenrol-user':
                    event.preventDefault();
                    confirmUnenrolUser(pathid, userid, name, trigger);
                    break;
            }
        };
    };

    // ════════════════════════════════════════════════════════════════════
    // Public init functions
    // ════════════════════════════════════════════════════════════════════

    var init = function() {
        var root = document.querySelector('[data-region="airpay-learningpath"]') || document.body;
        if (root.dataset.airpayLearningpathInit === '1') { return; }
        root.dataset.airpayLearningpathInit = '1';
        root.addEventListener('click', handleIndexClick);
    };

    var initView = function(pathid) {
        var root = document.querySelector('[data-region="airpay-path-view"]') || document.body;
        if (root.dataset.airpayPathviewInit === '1') { return; }
        root.dataset.airpayPathviewInit = '1';
        root.addEventListener('click', handleViewClick(pathid));
    };

    return {
        init: init,
        initView: initView
    };
});
